        [[f"Profile engine (FBref), on the {n_(VSF['common_queries'])} windows both engines cover", f"{VSF['full_median_rank']:.0f}", '', pc(VSF['full_recall@10']), pc(VSF['full_recall@25']), '', fmt_p(VSF['p@10'])]],
